326: /// (wave 9, D4) The verdict of a roster entry that declares a plan cap (`ext.c3.plan_caps`): an
327: /// instant 429 with no window text - `n >= 2` of them within 60 minutes of each other, newer than
328: /// the endpoint's newest usable reply - marks the entry `unavailable (plan quota: 429 twice in <n>
329: /// min, no window text; retry after <next reset>)` until the cap's next reset (the entry's
330: /// `reset_hint`, else 24 hours after the first hit of the pair), instead of the 10-minute burst. An entry
331: /// without a declared cap keeps `verdict` as it is.
332: pub fn plan_cap_verdict(
333:     verdict: PreflightVerdict,
334:     entry: &crate::roster::RosterEntry,
335:     health: Option<&crate::health::EndpointHealth>,
336:     now: DateTime<Utc>,
337: ) -> PreflightVerdict {
338:     use chrono::Duration;
339:     if entry.plan_caps.is_empty()
340:         || !(verdict.kind.is_empty() || verdict.kind == "quota-unknown-reset")
341:     {
342:         return verdict;
343:     }
344:     let Some(all_hits) = health.map(|h| &h.instant_429s) else {
345:         return verdict;
346:     };
347:     // (wave 9e, F76-1) a hit is pair evidence only while it lies inside the entry's CURRENT cap
348:     // period: for a hinted entry iff the reset that follows the hit has not passed yet
349:     // (`next_cap_reset(hint, hit) > now`), for an unhinted entry iff it is younger than 24 h at read
350:     // time. `endpoint_health` retains id-carrying hits far longer (35 days), so this per-entry bound
351:     // is applied here, where the hint is known, and every reader gets the same verdict regardless of
352:     // retention. A pair lying entirely before the last reset is no evidence.
353:     let hits: Vec<DateTime<chrono::FixedOffset>> = all_hits
354:         .iter()
355:         .copied()
356:         .filter(|hit| {
357:             let hit_utc = hit.with_timezone(&Utc);
358:             if entry.reset_hint.is_empty() {
359:                 now - hit_utc <= Duration::hours(24)
360:             } else {
361:                 next_cap_reset(&entry.reset_hint, hit_utc).is_none_or(|r| r > now)
362:             }
363:         })
364:         .collect();
365:     if hits.len() < 2 {
366:         return verdict;
367:     }
368:     // (wave 9f, F78-1) the newest QUALIFYING pair: ANY two distinct-id hits inside the period within
369:     // 60 min of each other. Fixing `second = hits[0]` (the single newest hit) and pairing only with
370:     // it let a later isolated instant 429 hide an established earlier pair, so the exhausted entry
371:     // read available before its declared reset. We scan newest-first and take the first `second` that
372:     // has a partner (the newest older hit) within the hour.
373:     let mut sorted = hits;
374:     sorted.sort_by(|a, b| b.cmp(a));
375:     let mut found = None;
376:     for (i, &second) in sorted.iter().enumerate() {
377:         if let Some(&first) = sorted[i + 1..]
378:             .iter()
379:             .find(|h| second - **h <= Duration::minutes(60))
380:         {
381:             found = Some((second, first));
382:             break;
383:         }
384:     }
385:     let Some((second, first)) = found else {
386:         return verdict;
387:     };
388:     let gap_min = ((second - first).num_seconds() as f64 / 60.0).ceil() as i64;
389:     let second_utc = second.with_timezone(&Utc);
390:     let until_utc = if entry.reset_hint.is_empty() {
391:         // the pair ages out of the read-time 24 h bound with its first hit
392:         first.with_timezone(&Utc) + Duration::hours(24)
393:     } else {
394:         next_cap_reset(&entry.reset_hint, second_utc).unwrap_or(second_utc + Duration::hours(24))
395:     };
396:     if until_utc <= now {
397:         return verdict;
398:     }
399:     let until = until_utc.with_timezone(second.offset());
400:     let until_iso = format_offset_iso(until);
401:     let mut v = verdict;
402:     v.state = "unavailable".into();
403:     v.kind = "quota".into();
404:     v.burst = false;
405:     v.hit = Some(second);
406:     v.until = Some(until);
407:     v.reason =
408:         format!("plan quota: 429 twice in {gap_min} min, no window text; retry after {until_iso}");
409:     v.preflight = format!("unavailable: {}", v.reason);
410:     v.refusal = format!(
411:         "provider {} is not usable: {} (the plan declares a {} cap); nothing was started (pass -SkipPreflight to launch anyway)",
412:         entry.provider,
413:         v.reason,
414:         entry.plan_caps.join("/")
415:     );
416:     v.label = format!(
417:         "unavailable ({}) - a real run is refused: {}",
418:         v.reason, v.refusal
419:     );
420:     v
421: }
